<script setup lang="ts">
import axios from 'axios'
import Button from 'primevue/button'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import Dialog from 'primevue/dialog'
import Message from 'primevue/message'
import { computed, reactive, ref } from 'vue'
import { z } from 'zod'
import { useToast } from 'primevue/usetoast'
import AppPageHeader from '@/components/app/AppPageHeader.vue'
import AppEmptyState from '@/components/state/AppEmptyState.vue'
import AppErrorState from '@/components/state/AppErrorState.vue'
import AppLoadingState from '@/components/state/AppLoadingState.vue'
import { cancelAbsence, createAbsence, listAbsences, listMyAbsences, updateAbsence } from '@/modules/absences/absences.service'
import { absenceStatusLabels, absenceTypeLabels, formatAbsenceDate } from '@/modules/absences/absences.presentation'
import { absenceTypes, type Absence, type AbsenceStatus, type AbsenceType } from '@/modules/absences/absences.types'
import { listActiveEmployees, type EmployeeOption } from '@/modules/employees/employees.service'
import { getUserFriendlyApiError } from '@/services/api-errors'
import { useAuthStore } from '@/stores/auth'

const authStore = useAuthStore()
const isUser = computed(() => authStore.role === 'User')
const toast = useToast()
const today = new Date()
const filters = reactive<{ from: string; to: string; status: '' | AbsenceStatus }>({ from: new Date(today.getFullYear(), today.getMonth(), 1).toISOString().slice(0, 10), to: new Date(today.getFullYear(), today.getMonth() + 1, 0).toISOString().slice(0, 10), status: '' })
const items = ref<Absence[]>([])
const employees = ref<EmployeeOption[]>([])
const loading = ref(false), loaded = ref(false), saving = ref(false), employeesLoading = ref(false)
const error = ref<string | null>(null), employeesError = ref<string | null>(null), formError = ref(''), conflict = ref<string | null>(null)
const formVisible = ref(false), selected = ref<Absence | null>(null), cancelTarget = ref<Absence | null>(null)
const form = reactive<{ employeeId: string; startDate: string; endDate: string; type: AbsenceType; reason: string; notes: string }>({ employeeId: '', startDate: filters.from, endDate: filters.to, type: 'Vacation', reason: '', notes: '' })
const schema = z.object({ employeeId: z.string().uuid('Selecciona un empleado.'), startDate: z.string(), endDate: z.string() }).refine((value) => value.endDate >= value.startDate, { path: ['endDate'], message: 'La fecha final no puede ser anterior a la fecha inicial.' })

async function load() { loading.value = true; error.value = null; try { const query = { from: filters.from, to: filters.to, ...(filters.status ? { status: filters.status } : {}) }; items.value = isUser.value ? await listMyAbsences(query) : await listAbsences(query); loaded.value = true } catch (exception) { error.value = getUserFriendlyApiError(exception) } finally { loading.value = false } }
async function loadEmployees() { employeesLoading.value = true; employeesError.value = null; try { employees.value = await listActiveEmployees(); if (!employees.value.length) employeesError.value = 'No hay empleados activos disponibles.' } catch { employeesError.value = 'No pudimos cargar los empleados.' } finally { employeesLoading.value = false } }
function openCreate() { selected.value = null; Object.assign(form, { employeeId: '', startDate: filters.from, endDate: filters.to, type: 'Vacation', reason: '', notes: '' }); formError.value = ''; formVisible.value = true; void loadEmployees() }
function openEdit(item: Absence) { selected.value = item; Object.assign(form, { employeeId: item.employeeId, startDate: item.startDate, endDate: item.endDate, type: item.type, reason: item.reason ?? '', notes: item.notes ?? '' }); formVisible.value = true }
async function save() { const validation = schema.safeParse(form); if (!validation.success) { formError.value = validation.error.issues[0]?.message ?? ''; return } saving.value = true; try { const payload = { startDate: form.startDate, endDate: form.endDate, type: form.type, reason: form.reason.trim() || null, notes: form.notes.trim() || null }; if (selected.value) await updateAbsence(selected.value.id, { ...payload, version: selected.value.version }); else await createAbsence({ ...payload, employeeId: form.employeeId }); formVisible.value = false; toast.add({ severity: 'success', summary: 'Listo', detail: selected.value ? 'Cambios guardados.' : 'Ausencia registrada correctamente.', life: 3000 }); await load() } catch (exception) { if (axios.isAxiosError(exception) && exception.response?.status === 409) { conflict.value = 'Esta ausencia fue modificada por otra persona. Actualiza la información e inténtalo nuevamente.' } else formError.value = getUserFriendlyApiError(exception) } finally { saving.value = false } }
async function confirmCancel() { if (!cancelTarget.value) return; try { await cancelAbsence(cancelTarget.value.id, cancelTarget.value.version); cancelTarget.value = null; await load() } catch (exception) { conflict.value = getUserFriendlyApiError(exception) } }
void load()
</script>

<template><section><AppPageHeader :title="isUser ? 'Mis ausencias' : 'Ausencias'" :description="isUser ? 'Consulta tus ausencias autorizadas.' : 'Registra y consulta ausencias autorizadas de los empleados.'" :action-label="isUser ? undefined : 'Registrar ausencia'" action-icon="pi pi-plus" @action="openCreate" /><Message v-if="conflict" severity="warn">{{ conflict }} <Button label="Actualizar" text @click="load" /></Message><form class="absence-filters app-surface" @submit.prevent="load"><label>Desde<input v-model="filters.from" type="date" /></label><label>Hasta<input v-model="filters.to" type="date" /></label><label>Estado<select v-model="filters.status"><option value="">Todos</option><option value="Active">Activa</option><option value="Cancelled">Cancelada</option></select></label><Button label="Consultar" type="submit" /></form><AppLoadingState v-if="loading" label="Cargando ausencias..." /><AppErrorState v-else-if="error" title="No pudimos cargar las ausencias." :description="error" @retry="load" /><AppEmptyState v-else-if="loaded && !items.length" title="No hay ausencias registradas para este período." description="Consulta otro rango." /><div v-else class="absence-list"><DataTable :value="items" data-key="id" class="absence-table"><Column header="Empleado"><template #body="{ data }"><strong>{{ data.employee.fullName }}</strong><small>{{ data.employee.employeeCode }}</small></template></Column><Column header="Tipo"><template #body="{ data }">{{ absenceTypeLabels[data.type] }}</template></Column><Column header="Desde"><template #body="{ data }">{{ formatAbsenceDate(data.startDate) }}</template></Column><Column header="Hasta"><template #body="{ data }">{{ formatAbsenceDate(data.endDate) }}</template></Column><Column header="Estado"><template #body="{ data }">{{ absenceStatusLabels[data.status] }}</template></Column><Column header="Motivo"><template #body="{ data }">{{ data.reason ?? 'Sin motivo' }}</template></Column><Column v-if="!isUser" header="Acciones"><template #body="{ data }"><template v-if="data.status === 'Active'"><Button label="Editar" text @click="openEdit(data)" /><Button label="Cancelar ausencia" text severity="secondary" @click="cancelTarget = data" /></template></template></Column></DataTable><div class="absence-cards"><article v-for="item in items" :key="item.id" class="app-surface absence-card"><strong>{{ item.employee.fullName }}</strong><small>{{ item.employee.employeeCode }}</small><span>Tipo: {{ absenceTypeLabels[item.type] }}</span><span>{{ formatAbsenceDate(item.startDate) }} — {{ formatAbsenceDate(item.endDate) }}</span><span>Estado: {{ absenceStatusLabels[item.status] }}</span><p>Motivo: {{ item.reason ?? 'Sin motivo' }}</p><div v-if="!isUser && item.status === 'Active'" class="absence-card__actions"><Button label="Editar" text @click="openEdit(item)" /><Button label="Cancelar ausencia" text severity="secondary" @click="cancelTarget = item" /></div></article></div></div><Dialog v-if="!isUser" :visible="formVisible" modal class="app-form-dialog" :header="selected ? 'Editar ausencia' : 'Registrar ausencia'" @update:visible="formVisible = false"><form class="absence-form" @submit.prevent="save"><label>Empleado<select v-model="form.employeeId" :disabled="Boolean(selected) || employeesLoading"><option value="">{{ employeesLoading ? 'Cargando empleados...' : 'Selecciona un empleado' }}</option><option v-for="employee in employees" :key="employee.id" :value="employee.id">{{ employee.fullName }} — {{ employee.employeeCode }}</option></select></label><Message v-if="employeesError" severity="warn">{{ employeesError }}</Message><label>Tipo de ausencia<select v-model="form.type"><option v-for="type in absenceTypes" :key="type" :value="type">{{ absenceTypeLabels[type] }}</option></select></label><label>Desde<input v-model="form.startDate" type="date" /></label><label>Hasta<input v-model="form.endDate" type="date" /></label><label>Motivo<input v-model="form.reason" maxlength="500" /></label><label>Notas<textarea v-model="form.notes" maxlength="1000" /></label><Message v-if="formError" severity="error">{{ formError }}</Message><div class="absence-card__actions"><Button label="Cancelar" text type="button" @click="formVisible = false" /><Button :label="selected ? 'Guardar cambios' : 'Registrar ausencia'" type="submit" :loading="saving" :disabled="saving || Boolean(employeesError)" /></div></form></Dialog><Dialog v-if="!isUser" :visible="Boolean(cancelTarget)" modal class="app-form-dialog" header="Cancelar ausencia" @update:visible="cancelTarget = null"><p>La ausencia quedará registrada en el historial como cancelada.</p><template #footer><Button label="Volver" text @click="cancelTarget = null" /><Button label="Cancelar ausencia" severity="secondary" @click="confirmCancel" /></template></Dialog></section></template>
